import type { NextConfig } from "next";

// Where the Spring Boot API lives. Read from .env.local in development.
// NOTE: rewrites are resolved when the server starts (dev) or at build time
// (production build), so set BACKEND_URL before `npm run build` if you rely on it.
const backendUrl = process.env.BACKEND_URL ?? "http://localhost:8080";

const nextConfig: NextConfig = {
  // Produce a self-contained server in .next/standalone for deployment.
  output: "standalone",

  // Generated by create-next-app: lets Turbopack process Tailwind CSS v4.
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },

  // The browser always calls relative URLs like /api/v1/tasks (same origin).
  // Next.js forwards them to Spring Boot, so we never need CORS in the browser.
  async rewrites() {
    return [
      {
        source: "/api/:path*",
        destination: `${backendUrl}/api/:path*`,
      },
    ];
  },
};

export default nextConfig;
